<script setup>
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue';
import { Button, Calendar, Cell, CellGroup, Checkbox, Collapse, CollapseItem, Dialog, Field, Picker, Popup, Radio, RadioGroup, Tab, Tabs, Uploader, showImagePreview } from 'vant';
import StudentCourseSettings from './StudentCourseSettings.vue';
import 'vant/lib/index.css';
const props=defineProps({controller:{type:Object,required:true}}),m=shallowRef(props.controller.snapshot()),a=props.controller.actions;
const unsubscribe=props.controller.subscribe(value=>m.value=value);
onBeforeUnmount(()=>{unsubscribe();props.controller.destroy();});
const picker=ref(false),expanded=ref([]),reset=ref(false),confirmed=ref(false),uploadMessage=ref('');
const pickerSelection=ref([]);
watch(picker,open=>{if(open)pickerSelection.value=[m.value.selected];});
watch(()=>m.value.selected,()=>{uploadMessage.value='';});
const columns=computed(()=>m.value.chapter?.nodes.map(n=>({text:n.title,value:n.id}))||[]);
const index=computed(()=>m.value.chapter?.nodes.findIndex(n=>n.id===m.value.selected)||0);
const last=computed(()=>m.value.record?.attempts.at(-1));
const sectionLabel=value=>String(value||'').replace(/\s*p\s*\d+\s*起/gi,'').trim();
const growthPath=computed(()=>{const c=m.value.calendar;if(!c)return '';const y=total=>155-total/Math.max(1,c.maximum)*120;return 'M40 '+y(c.baseline)+c.points.map((point,i)=>' H'+(40+(i+1)/(c.points.length+1)*620)+' V'+y(point.total)).join('')+' H660';});
const services=Object.fromEntries(['deepseek','voice'].map(kind=>[kind,{info:signal=>a.settingsInfo(kind,signal),save:value=>a.saveSettings(kind,value),clear:()=>a.clearSettings(kind),test:signal=>a.testSettings(kind,signal)}]));
function select({selectedValues}){if(m.value.view==='doubts')a.doubtTopic(selectedValues[0]);else a.choose(selectedValues[0]);picker.value=false;}
function photo(q,file){uploadMessage.value='';a.uploadPhoto(q.id,file.file);}
function formatDay(day){const key=`${day.date.getFullYear()}-${String(day.date.getMonth()+1).padStart(2,'0')}-${String(day.date.getDate()).padStart(2,'0')}`;return {...day,bottomInfo:m.value.calendar.days.includes(key)?'已学习':''};}
function duration(ms){const s=Math.floor((ms||0)/1000);return s<60?s+'秒':s<3600?Math.floor(s/60)+'分'+s%60+'秒':Math.floor(s/3600)+'小时'+Math.floor(s%3600/60)+'分';}
function gradeText(g){return g.feedback||g.summary||g.comment||'';}
function resetProgress(){if(a.reset(confirmed.value)){reset.value=false;confirmed.value=false;}}
</script>
<template>
 <nav class="course-return-nav"><Button tag="a" :href="m.backHref" data-growing-back>← 返回上一级</Button></nav>
 <main class="student-math-course course-shell">
  <template v-if="m.kind==='error'"><h1>{{m.title}}</h1><Button :url="m.backHref">返回目录</Button></template>
  <template v-else>
   <header class="course-heading"><div><p class="eyebrow">苏科版 · 八年级{{m.chapter.term==='upper'?'上':'下'}}册 · 第{{m.chapter.number}}章</p><h1>{{m.chapter.title}}课堂</h1></div><div class="progress-ring"><strong>{{m.read}}/{{m.chapter.nodes.length}}</strong></div></header>
   <nav class="course-tools-nav" aria-label="课堂工具"><Button v-if="m.wrongHref" @click="a.navigate(m.wrongHref)">本单元错题</Button><Button @click="a.open('interactive')">交互</Button></nav>
   <p v-if="m.message" role="status">{{m.message}}</p><p v-if="m.storageError" role="alert">{{m.storageError}}</p>
   <div v-if="m.view==='home'" class="course-layout">
    <div class="mobile-lesson-select"><label>切换本章知识点</label><Field :model-value="sectionLabel(m.node.section)+' · '+m.node.title+' · '+(m.metrics?.[index]?.label||'')" readonly is-link @click="picker=true"/><div class="lesson-study-meta"><small>累计学习 {{m.metrics?.[index]?.time}}</small><small>{{m.metrics?.[index]?.label}}</small></div></div>
    <nav class="lesson-list" aria-label="本章微课"><h2>按知识点学习</h2><Button v-for="(topic,i) in m.chapter.nodes" :key="topic.id" :aria-current="topic.id===m.selected?'page':undefined" @click="a.choose(topic.id)"><span class="lesson-name"><span class="section-label">{{sectionLabel(topic.section)}}</span>{{topic.title}}</span><span class="lesson-study-meta"><small>累计学习 {{m.metrics?.[i]?.time}}</small><small>{{m.metrics?.[i]?.label}}</small></span></Button></nav>
    <section class="lesson-panel"><p class="eyebrow">{{sectionLabel(m.node.section)}}</p><h2>{{m.node.title}}</h2><nav class="lesson-tabs" aria-label="学习步骤"><Button v-for="item in [{id:'learn',title:'图文讲解'},{id:'recall',title:'闭卷复述'},{id:'practice',title:'应用练习'}]" :key="item.id" :aria-current="m.tab===item.id?'page':undefined" @click="a.tab(item.id)">{{item.title}}</Button></nav>
    <section v-if="m.tab==='learn'" class="course-panel"><p class="lesson-copy">{{m.node.review}}</p><div class="course-figure" v-html="m.figure"/><h3 class="minor-title">一步一步理解</h3><ol class="steps"><li v-for="(step,i) in m.node.steps" :key="i">{{step}}</li></ol><h3 class="minor-title">跟着例子走一遍</h3><p class="worked">{{m.node.example}}</p><p v-if="m.node.pitfall" class="pitfall">易错提醒：{{m.node.pitfall}}</p><div class="course-actions"><Button @click="a.teach">小鸭讲课</Button><Button @click="a.play">播放讲解</Button><Button @click="a.stop">停止播放</Button><Button type="primary" @click="a.markRead">已理解，开始复述</Button></div></section>
    <section v-else-if="m.tab==='recall'" class="course-panel"><h2><label for="recall-content">用自己的话讲清楚</label></h2><Field id="recall-content" :model-value="m.record.draft" type="textarea" rows="8" autosize maxlength="6000" :disabled="m.busy" @update:model-value="a.draft"/><div class="course-actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.grade">AI检查解释</Button><Button v-if="m.busy" @click="a.cancelGrade">取消等待</Button></div><div v-if="m.feedback" v-html="m.feedback"/><section v-else-if="last"><h3>最近评分 {{last.score}} / 10</h3><p>{{last.feedback}}</p><ul><li v-for="(gap,i) in [...(last.criticalErrors||[]),...(last.gaps||[])]" :key="i">{{gap}}</li></ul></section><Collapse v-model="expanded"><CollapseItem title="历史复述记录" name="attempts"><article v-for="(attempt,i) in [...m.record.attempts].reverse()" :key="i"><p>{{attempt.at}} · {{attempt.score}} / 10</p><p class="preserve">{{attempt.answer}}</p><p>{{attempt.feedback}}</p></article></CollapseItem></Collapse></section>
    <section v-else class="course-panel application-round">
     <h2>应用练习 · {{m.questions.length}} 题</h2><p>选择题点选答案，解答题拍照上传。可提交已作答的题目，未作答题按未通过计。</p>
     <p v-if="m.practiceError" role="alert">{{m.practiceError}}</p><p v-if="uploadMessage" role="alert">{{uploadMessage}}</p>
     <article v-for="(q,i) in m.questions" :key="q.id" class="practice-question" :data-level="q.level" :data-question-id="q.id">
      <h3 class="question-prompt preserve">{{i+1}}. {{q.prompt}}</h3>
      <div v-if="q.diagram" class="practice-figure" v-html="q.diagram"/>
      <RadioGroup v-if="q.type==='choice'" :model-value="m.practice.choices[q.id]" :disabled="m.practice.busy" :aria-label="'第'+(i+1)+'题答案'" @update:model-value="value=>a.practiceChoice(q.id,value)">
       <Radio v-for="(option,j) in q.options" :key="j" :name="j"><span class="option-letter">{{'ABCD'[j]}}.</span> {{option}}</Radio>
      </RadioGroup>
      <template v-else>
       <div class="course-actions"><Uploader :disabled="q.pending||m.practice.busy" accept="image/jpeg,image/png,image/webp" capture="environment" result-type="file" :max-size="20*1024*1024" :after-read="file=>photo(q,file)" @oversize="uploadMessage='照片不能超过20MB，请压缩后再试。'"><Button :disabled="q.pending||m.practice.busy" :loading="q.pending">{{q.photos.length?'重新拍照 / 上传答案':'拍照 / 上传答案'}}</Button></Uploader><Button v-if="q.unsaved" :disabled="q.pending||m.practice.busy" @click="a.uploadPhoto(q.id)">重试保存照片</Button></div>
       <p v-if="q.message" role="status">{{q.message}}</p><div class="photo-list"><Button v-for="(image,j) in q.photos" :key="j" aria-label="查看作答原稿" @click="showImagePreview({images:q.photos,startPosition:j})"><img :src="image" alt="作答原稿"/></Button></div>
      </template>
      <section v-if="m.practice.result&&!m.practice.busy" class="question-result"><p>{{m.practice.result.items[i].unanswered?'未作答 · 0分':m.practice.result.items[i].passed?'✓ 答对 · 1分':m.practice.result.items[i].type==='solution'&&m.practice.result.items[i].score===null?'待复核 · 暂不计分':'未通过 · 0分'}}</p><p v-if="q.type==='choice'">正确答案：{{'ABCD'[q.answer]}} · {{q.explanation}}</p><p v-else-if="!m.practice.result.items[i].unanswered">{{q.history[0]?.feedback}}</p></section>
      <details v-if="q.history.length&&!m.practice.busy"><summary>查看批改记录</summary><article v-for="(g,j) in q.history" :key="j" class="grade-history"><h4>{{g.historical?'历史批改':'最近批改'}} · {{g.score}} 分 {{g.needsReview?'（待复核）':''}}</h4><p>{{gradeText(g)}}</p><p v-for="(correction,k) in g.corrections||[]" :key="k">{{correction.location}}：{{correction.issue}} {{correction.correction}}</p></article></details>
     </article>
     <div class="practice-submit"><p>已作答 {{m.practice.completed}} / {{m.practice.total}} 题</p><Button type="primary" :loading="m.practice.busy" :disabled="m.practice.busy||m.practice.uploading||!m.practice.completed||!!m.practiceError" @click="a.submitPractice">统一提交答案</Button><Button v-if="m.practice.busy" @click="a.cancelPractice">取消提交</Button><p v-if="m.practice.message" role="status">{{m.practice.message}}</p><p v-if="m.practice.result&&!m.practice.busy" class="round-score" role="status">本轮得分 {{m.practice.result.score}} / 10<span v-if="m.practice.result.pending"> · {{m.practice.result.pending}}题待复核</span><span v-if="!m.practice.result.saved"> · 尚未保存</span></p></div>
    </section>
    <footer><Button :disabled="index===0" @click="a.previous">上一个知识点</Button><Button :disabled="index===m.chapter.nodes.length-1" @click="a.next">下一个知识点</Button></footer>
    </section>
   </div>
   <section v-else-if="m.view==='doubts'" class="course-panel"><div class="section-heading"><h2>我有疑问</h2><Button icon="cross" aria-label="关闭答疑" @click="a.open('home')"/></div><p>围绕当前知识点提问；未发送草稿自动保存。</p><article v-for="(entry,i) in m.doubt.messages" :key="i"><h3>{{entry.role==='assistant'?'老师':'我'}}</h3><div v-if="entry.html" v-html="entry.html"/><p v-else class="preserve">{{entry.text}}</p></article><Field :model-value="m.doubt.draft" type="textarea" rows="5" maxlength="2000" label="我的问题" :disabled="m.doubtBusy" @update:model-value="a.doubtDraft"/><div class="course-actions"><Button type="primary" :loading="m.doubtBusy" :disabled="m.doubtBusy" @click="a.ask">发送问题</Button><Button v-if="m.doubtBusy" @click="a.cancelDoubt">取消等待</Button></div><p role="status">{{m.doubtMessage}}</p></section>
   <section v-else-if="m.view==='calendar'" class="course-panel"><div class="section-heading"><h2>学习日历</h2><Button icon="cross" aria-label="关闭学习日历" @click="a.open('home')"/></div><Calendar :poppable="false" :show-confirm="false" :style="{height:'440px'}" :min-date="new Date(2020,0,1)" :max-date="new Date(2040,11,31)" switch-mode="month" :formatter="formatDay" @select="a.calendarDay"><template #prev-month><Button icon="arrow-left" aria-label="上个月"/></template><template #next-month><Button icon="arrow" aria-label="下个月"/></template></Calendar><Button @click="a.calendarDay(new Date())">查看今天记录</Button><h3>{{m.calendar.day}} 学习记录</h3><p class="calendar-totals">新增掌握 {{m.calendar.totals.newCount}} 项 · AI复述 {{m.calendar.totals.grades}} 次 · 应用练习 {{m.calendar.totals.practice}} 轮 · 专项 {{m.calendar.totals.special}} 题 · 有效学习 {{duration(m.calendar.totals.ms)}}</p><p v-if="!m.calendar.rows.length">这一天还没有学习记录。</p><CellGroup><Cell v-for="row in m.calendar.rows" :key="row.id" :title="row.title" :label="'阅读 '+(row.reads||0)+' 次 · AI评分 '+(row.grades||0)+' 次（最高 '+(row.best||0)+'/10） · 应用 '+(row.practice||0)+' 轮 · 专项 '+(row.special||0)+' 题 · 答对 '+(row.correct||0)+'/'+(row.total||0)+' 题 · 有效学习 '+duration(row.ms)" is-link @click="a.choose(row.id)"/></CellGroup><h3>成长记录：已掌握 {{m.calendar.total}} / {{m.calendar.maximum}}</h3><svg viewBox="0 0 710 200" style="width:100%;height:auto" role="img" aria-label="本章累计首次达标知识点成长曲线"><title>首次达标累计成长曲线</title><line x1="40" y1="155" x2="660" y2="155" stroke="#9aa89d"/><text x="12" y="40">{{m.calendar.maximum}}</text><text x="18" y="158">0</text><path :d="growthPath" fill="none" stroke="#22634b" stroke-width="3"/><text x="40" y="185">{{m.calendar.points[0]?.date||'暂无带日期记录'}}</text></svg><p v-if="m.calendar.baseline">历史达标 {{m.calendar.baseline}} 个知识点，保留原成绩。</p><p v-for="point in m.calendar.points" :key="point.date">{{point.date}} · 累计掌握 {{point.total}} 个知识点</p><Collapse v-model="expanded"><CollapseItem title="本章知识点进度" name="metrics"><Cell v-for="row in m.metrics" :key="row.id" :title="row.title" :label="row.label+' · '+row.time" is-link @click="a.choose(row.id)"/></CollapseItem></Collapse></section>
   <section v-else-if="m.view==='settings'" class="course-panel"><StudentCourseSettings :services="services" @close="a.open('home')"/><Button @click="confirmed=false;reset=true">重置本章进度</Button><p>仅重置当前章节；其他章节、奖励和作答原稿保留。</p></section>
   <Popup v-model:show="picker" position="bottom" round teleport="body" aria-label="选择知识点"><Picker v-model="pickerSelection" title="选择知识点" :columns="columns" @confirm="select" @cancel="picker=false"><template #cancel><Button icon="cross" aria-label="关闭知识点选择" style="width:44px;height:44px;padding:0" @click="picker=false"/></template></Picker></Popup>
   <Dialog v-model:show="reset" title="重置本章进度"><div class="reset-content"><p>确认重置当前章节？奖励、其他章节和手写原稿将保留。</p><Checkbox v-model="confirmed">我确认重置本章进度</Checkbox></div><template #footer><div class="course-actions reset-content"><Button icon="cross" aria-label="关闭重置确认" style="width:44px;height:44px;padding:0" @click="reset=false;confirmed=false"/><Button type="danger" :disabled="!confirmed" @click="resetProgress">重置本章进度</Button></div></template></Dialog>
  </template>
  <Collapse v-model="expanded" class="course-more"><CollapseItem title="更多课堂工具" name="tools"><div class="course-actions"><Button @click="a.navigate(m.backHref)">目录</Button><Button @click="a.navigate(m.summaryHref)">单元总结</Button><Button @click="a.navigate(m.graphHref)">知识图谱</Button><Button @click="a.open('doubts')">我有疑问</Button><Button @click="a.open('calendar')">学习日历</Button><Button @click="a.open('settings')">学习设置</Button></div></CollapseItem></Collapse>
 </main>
</template>
